schema_excerpt:
interface Response {
  entryUpdates: {
    characterUpdates?: {
      name: string; // Exact name of existing character to update
      changes: {
        status?: "active" | "inactive" | "deceased"; // active=present, inactive=away, deceased=dead
        relationship?: string; // New relationship to protagonist
        newTraits?: string[]; // Personality traits to add
        removeTraits?: string[]; // Traits no longer applicable
        visualDescriptors?: {
          face?: string; // Skin tone, facial features, expression, age indicators
          hair?: string; // Color, length, style, texture (e.g., "wavy auburn hair to shoulders")
          eyes?: string; // Color, shape, notable features (e.g., "sharp green eyes")
          build?: string; // Height, body type, posture (e.g., "tall and lean", "broad-shouldered")
          clothing?: string; // Full outfit description (e.g., "worn leather armor over gray tunic")
          accessories?: string; // Jewelry, weapons, bags, distinctive items (e.g., "silver pendant, sword at hip")
          distinguishing?: string; // Scars, tattoos, birthmarks if any (e.g., "scar across left cheek")
        }; // Complete visual ap

...[middle truncated]...

clothing?: string; // Full outfit description (e.g., "worn leather armor over gray tunic")
        accessories?: string; // Jewelry, weapons, bags, distinctive items (e.g., "silver pendant, sword at hip")
        distinguishing?: string; // Scars, tattoos, birthmarks if any (e.g., "scar across left cheek")
      }; // Complete visual appearance - ALL categories should be filled
      status?: "active" | "inactive" | "deceased"; // active if present in scene
    }[];
    newLocations?: {
      name: string; // Location's proper name
      description?: string; // One sentence description
      visited?: boolean; // true if protagonist has been here
      current?: boolean; // true if this is the current scene location
    }[];
    newItems?: {
      name: string; // Item name
      description?: string; // One sentence description
      quantity?: number; // How many (default 1)
      location?: string; // inventory, worn, or location name
      equipped?: boolean; // true if currently worn/wielded
    }[];
    newStoryBeats?: {
      title: string; // Short title (3-6 words)
      description?: string; // What happened or needs to happen
      type?: "milestone" | "quest" | "revelation" | "event" | "plot_point"; // milestone, quest, revelation, event, or plot_point
      status?: "pending" | "active" | "completed" | "failed"; // pending=upcoming, active=in-progress, completed=done
    }[];
  };
  scene: {
    currentLocationName?: string | null; // Name of current scene location, or null
    presentCharacterNames?: string[]; // Names of characters physically present
    timeProgression?: "none" | "minutes" | "hours" | "days"; // none=instant, minutes=conversations, hours=travel, days=sleep
  };
}

Output ONLY the JSON object, no other text or markdown.

